    // -- le carnet
    "Le carnet de {1}": "دفتر {1}",
    "M39ol {1} — {2} · {3} présence{4}\nCe que tu as donné à la maison : ta présence aux sessions, ce que tu portes, ce que tu tiens.{5}":
      "المعقول {1} — {2} · {3} حضور\nما أعطيته للدار: حضورك في الجلسات، ما تحمله، وما تلتزم به.\n{5}",
    "Il se reçoit d'un autre — le témoin, la salle, le bureau. Jamais d'ici.": "يُستلم من آخر — الشاهد، القاعة، المكتب. لا من هنا أبدًا.",
    "Encore {1} pour devenir {2}.": "بقي {1} لتصير {2}.",
    "Sna3a {1} — {2}, {3}\nCe que tu sais faire : {4} Ta7addi sur {5} à l'établi{6}.\n{7}":
      "الصنعة {1} — {2}، {3}\nما تُحسن فعله: {4} تحدّي من {5} في الورشة{6}.\n{7}",
    ", et {1} bonne{2} réponse{3} au rihal": "، و{1} جواب صحيح عند الرَّحْل",
    "Dhakira {1} — {2}, {3}\nCe que tu sais de ton pays : {4} page{5} de la Rihla sur {6}, au sandouq de la Khizana.":
      "الذاكرة {1} — {2}، {3}\nما تعرفه عن بلدك: {4} صفحة من الرحلة من أصل {6}، في صندوق الخزانة.",
    "Les trois ne se changent pas l'un en l'autre. La technique et la mémoire se gagnent seul ; le rang, lui, ne se gagne qu'ensemble.":
      "الثلاثة لا يتحوّل أحدها إلى الآخر. التقنية والذاكرة تُكسبان وحدك؛ أما الرتبة فلا تُكسب إلا معًا.",
