    "Page {1} sur {2} — « {3} », {4}.{5}": "الصفحة {1} من {2} — «{3}»، {4}.\n{5}",
    "{1} — {2} — {3} — veille sur cette page.": "{1} — {2} — {3} — يسهر على هذه الصفحة.",
    "Un indice demandé : la page vaudra {1} Sna3a.": "طُلب تلميح: ستساوي الصفحة {1} صنعة.",
    "Ce n'est pas ça. Nsyan sourit… Relis, demande un indice, ou va poser la question à ton compagnon.":
      "ليس هذا. نسيان يبتسم… أعد القراءة، اطلب تلميحًا، أو اذهب فاسأل رفيقك.",
    "Écris une réponse d'abord.": "اكتب جوابًا أولًا.",
    "C'était la dernière page.": "كانت الصفحة الأخيرة.",
    "Il reste {1} page{2} dans le sandouq.": "بقي في الصندوق {1} من الصفحات.",
    "Page retrouvée": "صفحة مستعادة",
    "☑ « {1} » — {2}.\n+{3} Dhakira{4}\nLa voie exercée : « {5} ». Elle s'entraîne ici, elle se note à l'établi.":
      "☑ «{1}» — {2}.\n+{3} ذاكرة{4}\nالطريق التي تدرّبت عليها: «{5}». تُمارَس هنا، وتُحسب في الورشة.",
    " — trouvée sans indice.": " — وُجدت بلا تلميح.",
    "Source : {1}": "المصدر: {1}",
    "{1} Ce que tu viens d'apprendre se pose sur ton tapis — étale, ne raconte pas.": "{1} ما تعلّمته للتوّ يوضع على بساطك — افرش، لا تحكِ.",
