      "التحدّي {1} من {2} — «{3}».\nالطريق «{4}»: {5}\n(أما تحدّيات الشركات فلا تُصحَّح هنا: تُسلَّم. لا شيء منها مفتوح الآن.)",
    "Ta7addi {1} sur {2} — « {3} ».\nVoie « {4} » : {5}": "التحدّي {1} من {2} — «{3}».\nالطريق «{4}»: {5}",
    "Pas celle-là. Relis l'énoncé : la réponse s'y trouve.": "ليست هذه. أعد قراءة النص: الجواب فيه.",
    "L'échauffement": "الإحماء",
    "☑ {1} — du premier coup.": "☑ {1} — من أول محاولة.",
    "☑ {1}.": "☑ {1}.",
