    "Un mot par jour, le même pour tous, six essais. Vert : la bonne lettre à la bonne place. Ocre : la lettre y est, mais ailleurs.": "كلمة في اليوم، هي نفسها للجميع، وست محاولات. الأخضر: الحرف الصحيح في مكانه. المُغرّ: الحرف موجود، لكن في مكان آخر.",
