    "La prochaine s'écrit à minuit, heure de Fès. Aucun point : la kelma compte des jours — jouer compte, perdre ne casse rien. Ta goutte du jour est dans la fontaine du Sahn.": "الكلمة القادمة تُكتب عند منتصف الليل، بتوقيت فاس. لا نقاط: الكلمة تعدّ الأيام — اللعب يُحسب، والخسارة لا تكسر شيئًا. قطرتك لهذا اليوم في خصّة الصحن.",
