    "Trois verres. Tiens pour lever la théière et verser : plus c'est haut, plus la rghwa monte — mais plus le filet danse. Lâche pour redescendre.": "ثلاث كؤوس. اضغط مطوّلًا لترفع البرّاد وتسكب: كلما علا، علت الرغوة — لكن الخيط يرقص أكثر. اترك لتُنزله.",
