    "Servir encore": "قدّم مرة أخرى",
    "Ta meilleure rghwa : {1}. Ta goutte du jour est dans la fontaine du Sahn.": "أحسن رغوة لك: {1}. قطرتك لهذا اليوم في خصّة الصحن.",
    // --- Lkhessa ta3mer : la fontaine se remplit
    "Lkhessa ta3mer — la fontaine se remplit": "الخصّة تعمر — الخصّة تمتلئ",
    "L'eau vient d'en haut, coule vers tous, et personne ne la garde pour lui. Cette semaine, elle monte avec ce que chacun fait. Pleine avant dimanche soir : la semaine d'après, les lanternes de la cour restent allumées — pour tout le monde.": "الماء يأتي من فوق، يجري نحو الجميع، ولا أحد يحتفظ به لنفسه. هذا الأسبوع، يعلو بما يفعله كل واحد. ممتلئة قبل مساء الأحد: في الأسبوع الموالي، تبقى فوانيس الصحن مضاءة — للجميع.",
