    "Une goutte par geste, par jour et par personne : c'est la base qui compte, pas l'écran. La fontaine ne donne aucun point — elle est à tous.": "قطرة لكل فعل، في كل يوم، لكل شخص: القاعدة هي التي تعدّ، لا الشاشة. الخصّة لا تعطي أي نقطة — إنها للجميع.",
