    "La maison a assez interrogé le modèle aujourd'hui. Reviens demain.": "الدار سألت النموذج بما يكفي اليوم. عُد غدًا.",
    "Cet essai est déjà jugé.": "هذه المحاولة حُكم عليها من قبل.",
