    "le plus court : {1} — {2}": "الأقصر: {1} — {2}",
    "Le premier trou réussi rapporte de la Sna3a (voie « dire juste ») : 10, et 15 sous le par. Les records suivants ne rapportent que la place au tableau. Le prompt ne peut jamais contenir la réponse.": "أول نجاح في كل حفرة يعطي صنعة (طريق «القول الصحيح»): 10، و15 تحت المعيار. الأرقام القياسية بعد ذلك لا تعطي إلا المكانة في اللوحة. البرومبت لا يمكن أبدًا أن يحتوي على الجواب.",
    "1 caractère · par {1}": "حرف واحد · المعيار {1}",
