    "Envoyer au modèle": "أرسل إلى النموذج",
    "Le modèle réfléchit…": "النموذج يفكّر…",
    "Trou réussi en {1} caractères.": "حفرة ناجحة في {1} حرفًا.",
    "Pas encore.": "ليس بعد.",
    "Le modèle a répondu": "أجاب النموذج",
    "+{1} Sna3a — ton premier passage sur ce trou.": "+{1} صنعة — أول نجاح لك في هذه الحفرة.",
    "+{1} Sna3a — ton premier passage sur ce trou, sous le par.": "+{1} صنعة — أول نجاح لك في هذه الحفرة، تحت المعيار.",
    "Record personnel : {1} caractères.": "رقم قياسي شخصي: {1} حرفًا.",
    "Tu es premier au tableau de ce trou.": "أنت الأول في لوحة هذه الحفرة.",
    "Rang {1} au tableau de ce trou.": "المرتبة {1} في لوحة هذه الحفرة.",
    "Les plus courts": "الأقصر",
    "Il te reste 1 essai aujourd'hui. Le tableau montre la longueur, jamais le prompt.": "بقيت لك محاولة واحدة اليوم. اللوحة تُظهر الطول، لا البرومبت أبدًا.",
    "Il te reste {1} essais aujourd'hui. Le tableau montre la longueur, jamais le prompt.": "بقيت لك {1} محاولات اليوم. اللوحة تُظهر الطول، لا البرومبت أبدًا.",
    // --- v5.1 — les jeux de la zawia : le menu, Ba Driss, le Wird, le carnet (jeux.js)
    "Les jeux de la zawia": "ألعاب الزاوية",
    "Atay — trois verres, de haut": "أتاي — ثلاثة كيسان، من الفوق",
    "Wach hadi IA ? — trouver l'IA": "واش هادي IA؟ — لقى الذكاء الاصطناعي",
    "Chkoun Nsyan ?": "شكون نسيان؟",
    "Wach hadi IA ?": "واش هادي IA؟",
    "Ba Driss, depuis la porte": "با إدريس، من عند الباب",
    "{1} ! Viens voir. La cour a de nouveaux jeux. Aucun ne donne de points : on y joue pour le plaisir — et pour la fontaine.": "{1}! أجي تشوف. الدار فيها ألعاب جديدة. حتى وحدة ما كتعطي النقط: كنلعبو على خاطرنا — وعلى خاطر الخصّة.",
    "Chaque jour, trois. Lkelma d'lyoum, au lawh du mur nord de la Madrasa : un mot, le même pour tous, six essais. Et l'Atay, sous les orangers du riad : trois verres, versés de haut.": "كل نهار، ثلاثة. «الكلمة ديال اليوم» فاللوح ديال الحيط الشمالي ديال المدرسة: كلمة وحدة، هي هي للجميع، وستة ديال المحاولات. و«أتاي» تحت برتقال الرياض: ثلاثة كيسان، كيتكبّو من الفوق.",
    "Le troisième, c'est Qlil w mfid, à l'établi du prompt, au coin de la Madrasa : faire dire au modèle exactement ce qu'on demande, avec le prompt le plus court.": "والثالث هو «قليل ومفيد»، فمنضدة البرومبت، فقنت المدرسة: تخلّي النموذج يقول بالضبط داكشي اللي طلبتي، بأقصر برومبت.",
    "Chaque partie verse une goutte à la fontaine du Sahn. Si la cour la remplit dans la semaine, les lanternes restent allumées la semaine d'après — pour tout le monde.": "كل لعبة كتكبّ قطرة فخصّة الصحن. إلا عمّراتها الدار فالسيمانة، الفنارات كيبقاو شاعلين السيمانة اللي من بعد — للجميع.",
    "Et pour tes amis, sans compte : Chkoun Nsyan ?, pour trouver qui a oublié le mot, et Wach hadi IA ?, dix duels pour démasquer l'IA. Envoie-leur le lien.": "ولصحابك، بلا حساب: «شكون نسيان؟» باش تلقاو شكون نسى الكلمة، و«واش هادي IA؟»، عشرة ديال المبارزات باش تكشفو الذكاء الاصطناعي. صيفط ليهم الرابط.",
    "Tout est au Menu, sous « Jouer ». Et le Wird te dit chaque jour ce qui reste à jouer.": "كلشي فالقائمة، تحت «العب». والورد كيقول ليك كل نهار شنو باقي ما لعبتي.",
    "Les jeux du jour": "ألعاب اليوم",
    "joué aujourd'hui": "تلعبات اليوم",
    "Ton atay est servi : {1}/100 aujourd'hui.": "أتاي ديالك تقدّم: {1}/100 اليوم.",
    "Trois verres t'attendent sous les orangers du riad.": "ثلاثة كيسان كيتسناوك تحت برتقال الرياض.",
    "Un trou joué aujourd'hui à l'établi du prompt.": "حفرة تلعبات اليوم فمنضدة البرومبت.",
    "Un trou de golf du prompt t'attend, à l'établi du coin de la Madrasa.": "حفرة ديال غولف البرومبت كتسناك، فالمنضدة اللي فقنت المدرسة.",
    "Entre amis, sans compte :": "مع الصحاب، بلا حساب:",
    "Les jeux de la zawia — aucun point, que du jeu.\nLkelma d'lyoum · jours joués {1} · série {2} · record {3}\nAtay · services {4} · meilleure tasse {5}/100\nQlil w mfid · trous réussis {6} sur {7}\nLa fontaine · tes gouttes aujourd'hui {8}": "ألعاب الزاوية — حتى نقطة، غير اللعب.\nالكلمة ديال اليوم · أيام ملعوبة {1} · السلسلة {2} · الرقم القياسي {3}\nأتاي · الخدمات {4} · أحسن كاس {5}/100\nقليل ومفيد · حفر ناجحة {6} من {7}\nالخصّة · قطراتك اليوم {8}",
    // --- v5.2 — la Rihla : Fès en monde ouvert (fes.js, rihla.js, jeu.js)
    "Bab ar-Rihla": "باب الرحلة",
    "La porte du temps. Derrière elle, la médina de Fès — telle que Nsyan l'a laissée.": "باب الزمن. موراه، مدينة فاس — كيف خلّاها النسيان.",
    "Et au fond de la Khizana, la porte du temps s'est ouverte : Bab ar-Rihla. Derrière, Fès t'attend — grise, et qui n'attend que toi.": "وفي آخر الخزانة، باب الزمن تحلّ: باب الرحلة. موراه، فاس كتسناك — رمادية، وما كتسنى غير نتا.",
    "La Rihla — sortir dans Fès": "الرحلة — اخرج لفاس",
    "Rentrer à la zawia": "رجع للزاوية",
    "La Rihla — Fès": "الرحلة — فاس",
    "Fès": "فاس",
    "Fès · Nfs {1}/{2} · {3} mouzounat": "فاس · النفس {1}/{2} · {3} موزونات",
    "La porte ne s'ouvre pas encore. Finis d'abord ce que le mou'allim te montre.": "الباب مازال ما كيتحلش. كمّل أولا داكشي اللي كيوريك المعلّم.",
    "Une étoile de zellige ! +{1} mouzounat · {2} sur {3}": "نجمة ديال الزليج! +{1} موزونات · {2} من {3}",
    "Tu connais ce quartier, maintenant : {1}. Il reprend ses couleurs. +{2} mouzounat.": "دابا كتعرف هاد الحومة: {1}. رجعو ليها ألوانها. +{2} موزونات.",
    "Toute la médina a repris ses couleurs. Fès te reconnaît.": "المدينة كاملة رجعو ليها ألوانها. فاس عرفاتك.",
    "Ton souffle : {1}/{2}": "نفسك: {1}/{2}",
