    "Pas à cette heure-ci : de {1} h à {2} h, heure de Casablanca.": "ماشي فهاد الساعة: من {1} حتى {2}، بتوقيت الدار البيضاء.",
    "Ton souffle est plein. Garde tes mouzounat pour plus tard.": "نفسك عامر. خبّي موزوناتك لمن بعد.",
