    "C'est fait pour aujourd'hui. Reviens demain.": "تدارت اليوم. رجع غدا.",
    "Tu n'as plus assez de souffle. Mange d'abord.": "ما بقاش عندك النفس. كول أولا.",
    "Cette porte ne se paie pas.": "هاد الباب ما كيتخلّصش.",
    "C'est déjà ouvert.": "راه محلول.",
    "Il te manque des mouzounat : c'est {1}.": "خاصّك الموزونات: بـ{1}.",
