    "Ce n'est pas ça. {1}": "ماشي هي. {1}",
    "C'est ça. Tu connais la ville : monte quand tu veux.": "هي هادي. كتعرف المدينة: طلع وقتما بغيتي.",
    "Un sachet d'olives noires, bien serré.": "شكارة ديال الزيتون الكحل، مزيّرة مزيان.",
    "Un arbre": "شجرة", "Un bassin": "صهريج", "Une porte": "باب",
    "Une lanterne de la médina. Le soir, Fès s'allume par morceaux.": "فانوس ديال المدينة. فالعشية، فاس كتشعل حتة بحتة.",
    "Un arbre de Fès. Il a vu passer plus de monde que toi, et il se souvient de chacun.": "شجرة من فاس. شافت دوّز ناس كثر منك، وكتفكر كل واحد.",
