    "Dans la vraie vie : fondateurs, commerciaux, business developers, partenariats, acheteurs.": "في الحياة الحقيقية: المؤسّسون، التجاريون، مطوّرو الأعمال، الشراكات، المشترون.",
    "Dans la vraie vie : contenu, communication, médias, design, vidéo, documentation.": "في الحياة الحقيقية: المحتوى، التواصل، الإعلام، التصميم، الفيديو، التوثيق.",
    "Mt3ellem, ta ferracha est un outil qui tourne — vibe codé ou écrit à la main, pourvu qu'un autre s'en serve.": "متعلّمًا، فرّاشتك أداة تعمل — بالـ vibe coding أو مكتوبة باليد، ما دام غيرك يستعملها.",
    "Mt3ellem, ta ferracha est un Talib accompagné pendant son Arb3ine, ou une halqa que tu as animée.": "متعلّمًا، فرّاشتك طالب واكبته في أربعينه، أو حلقة نشّطتها.",
    "Mt3ellem, ta ferracha est une relecture : un livrable ou une page relus, avec ce qui casse dit à voix haute.": "متعلّمًا، فرّاشتك مراجعة: إنجاز أو صفحة أعدت قراءتها، وقلت بصوت عالٍ ما ينكسر فيها.",
    "Mt3ellem, ta ferracha est une affaire conclue à la Rahba, ou un partenaire amené à la maison.": "متعلّمًا، فرّاشتك صفقة أُبرمت في الرحبة، أو شريك جئت به إلى الدار.",
    "Mt3ellem, ta ferracha est une notice qu'un autre peut suivre — une wasfa, un tuto, un post-mortem.": "متعلّمًا، فرّاشتك دليل يستطيع غيرك اتّباعه — وصفة، أو شرح، أو تشريح لفشل.",
    "M3ellem, tu prends un Talib de ta tariqa et tu lui apprends le geste : c'est la silsila.": "معلّمًا، تأخذ طالبًا من طريقتك وتعلّمه الحركة: هذه هي السلسلة.",
    "M3ellem, tu mènes un Talib jusqu'à Mt3ellem — la ligne à +300 de la charte, et c'est ton métier.": "معلّمًا، تقود طالبًا حتى يصير متعلّمًا — سطر الـ +300 في الميثاق، وهذه مهنتك.",
    "M3ellem, tu apprends à un Talib à lire une source avant de croire un modèle.": "معلّمًا، تعلّم طالبًا أن يقرأ المصدر قبل أن يصدّق النموذج.",
    "M3ellem, tu apprends à un Talib à vendre sans hchouma — et jamais dans la halqa.": "معلّمًا، تعلّم طالبًا أن يبيع بلا حشومة — وأبدًا داخل الحلقة.",
    "M3ellem, tu apprends à un Talib à écrire pour sa mère : si elle ne comprend pas, ce n'est pas écrit.": "معلّمًا، تعلّم طالبًا أن يكتب لأمّه: إن لم تفهم، فلم يُكتب شيء.",
    "Ton premier geste : un Ta7addi à l'établi de la Madrasa, puis le premier Masar.": "أول حركة لك: تحدّي في ورشة المدرسة، ثم أول مسار.",
    "Ton premier geste : une page du sandouq, puis ton étal au Souk.": "أول حركة لك: صفحة من الصندوق، ثم بسطتك في السوق.",
    "Ton premier geste : salue trois personnes au Sahn, et note le mercredi de la maison au Riwaq.": "أول حركة لك: سلّم على ثلاثة في الصحن، وسجّل أربعاء الدار في الرواق.",
    "Ton premier geste : salue trois personnes au Sahn, et pose une question au cercle.": "أول حركة لك: سلّم على ثلاثة في الصحن، واطرح سؤالًا على الحلقة.",
    "Ton premier geste : une page du sandouq, sa source lue ; puis cinq questions au rihal.": "أول حركة لك: صفحة من الصندوق، مع قراءة مصدرها؛ ثم خمسة أسئلة عند الرَّحل.",
    "Ton premier geste : une page du sandouq, avec sa source lue jusqu'au bout.": "أول حركة لك: صفحة من الصندوق، مع قراءة مصدرها حتى النهاية.",
    "Ton premier geste : sors par le Bab et pose ton étal sur la Rahba.": "أول حركة لك: اخرج من الباب وابسط بسطتك في الرحبة.",
    "Ton premier geste : cinq lignes dans ton daftar, puis propose une wasfa au Kounnach.": "أول حركة لك: خمسة أسطر في دفترك، ثم اقترح وصفة للكنّاش.",
    "Fqih, tu valides les ijazat de toutes les tariqat ; Morchid, tu gardes la culture. Les degrés du haut servent toute la maison.": "فقيهًا، تُجيز إجازات كل الطرق؛ مرشدًا، تحرس الثقافة. الدرجات العليا تخدم الدار كلّها.",
    "On ne te demande rien pendant l'Arb3ine. Le quarantième jour, on pose sa première ferracha — et on dit d'où l'on sert.": "لا يُطلب منك شيء خلال الأربعين. في اليوم الأربعين، يبسط المرء أول فرّاشته — ويقول من أين يخدم.",
