    // ---- v8.7 — le Derb t-Tadamoun (tadamoun.js, rahba.js, le panneau du Souk) ----
    "L'arganier du Derb": "شجرة أركان الدرب",
    "L'arganier. Il ne pousse presque nulle part ailleurs que chez nous, dans le Souss — et des villages entiers en vivent, parce que les femmes en ont fait de l'huile, ensemble, en coopérative.":
      "الأركان. لا ينبت تقريبًا في أي مكان آخر غير بلادنا، في سوس — وتعيش منه دواوير بأكملها، لأن النساء صنعن منه الزيت، معًا، في تعاونية.",
    "Les chèvres y grimpent. Personne ne leur a appris : elles ont regardé les autres le faire.": "الماعز تتسلّقه. لم يعلّمها أحد: رأت غيرها يفعل ذلك.",
    "Le puits de la Twiza": "بئر التويزة",
    "Le puits de la Twiza. Au douar, on ne creuse jamais un puits seul : chacun vient donner sa journée, et l'eau est à tous. C'est ça, la Twiza.":
      "بئر التويزة. في الدوار، لا يحفر أحد البئر وحده: يأتي كل واحد ليعطي يومه، والماء للجميع. هذه هي التويزة.",
    "Les projets de la ruelle attendent des mains. Regarde ce dont chacun a besoin : une heure de toi peut valoir plus qu'un don.":
      "مشاريع الدرب تنتظر الأيادي. انظر ما يحتاجه كل مشروع: ساعة منك قد تساوي أكثر من تبرّع.",
    "Lalla Ito, de la Twiza": "لالة إيطو، من التويزة",
    "Mrahba bik f Derb t-Tadamoun, {1}. Ici, pas de produits à vendre : des projets qui ont besoin des autres.": "مرحبا بيك ف درب التضامن، {1}. هنا لا منتجات للبيع: مشاريع تحتاج إلى الآخرين.",
    "Personne n'a encore posé de projet dans la ruelle. Le premier qui le fait l'ouvre pour tous.": "لم يضع أحد مشروعًا في الدرب بعد. أول من يفعل يفتحه للجميع.",
    "{1} projet attend des mains aujourd'hui. Chacun dit ce dont il a besoin.": "{1} مشروع ينتظر الأيادي اليوم. كل مشروع يقول ما يحتاجه.",
    "{1} projets attendent des mains aujourd'hui. Chacun dit ce dont il a besoin.": "{1} مشاريع تنتظر الأيادي اليوم. كل مشروع يقول ما يحتاجه.",
    "Une coopérative, une association, une entreprise sociale, un projet RSE, une initiative de quartier — ou juste une idée. Tout a sa place ici, même ce qui n'a pas encore de nom.":
      "تعاونية، جمعية، مقاولة اجتماعية، مشروع للمسؤولية الاجتماعية، مبادرة في الحي — أو مجرد فكرة. لكل شيء مكانه هنا، حتى ما ليس له اسم بعد.",
    "Tu peux aider ? Dis-le à son porteur : ton mot part dans sa boîte. Ton entreprise veut adopter un projet ? Écris au bureau, il fera le lien.":
      "تستطيع المساعدة؟ قلها لصاحب المشروع: كلمتك تصل إلى صندوقه. مقاولتك تريد أن تتبنّى مشروعًا؟ اكتب إلى المكتب، وهو سيربط بينكما.",
    "Ton projet a sa place, sous l'auvent vert à ton nom. Et ici, la zawia ne prend rien : pas de smsra sur la solidarité.":
      "لمشروعك مكانه، تحت المظلة الخضراء باسمك. وهنا لا تأخذ الزاوية شيئًا: لا سمسرة على التضامن.",
    "Tu portes un projet ? Pose-le depuis ta ferracha, « au Derb t-Tadamoun ». Et ici, la zawia ne prend rien : pas de smsra sur la solidarité.":
      "تحمل مشروعًا؟ ضعه من فرّاشتك، «في درب التضامن». وهنا لا تأخذ الزاوية شيئًا: لا سمسرة على التضامن.",
    "Et par le passage du mur est : le Derb t-Tadamoun. Là, pas de marchandage — des projets solidaires qui cherchent des mains.":
      "ومن الممرّ في الحائط الشرقي: درب التضامن. هناك لا مساومة — مشاريع تضامنية تبحث عن أيادٍ.",
    "Une place du Derb": "مكان في الدرب",
    "Une place du Derb, sous l'auvent vert. Un projet solidaire posé depuis sa ferracha, « au Derb t-Tadamoun », vient s'étaler ici.":
      "مكان في الدرب، تحت المظلة الخضراء. المشروع التضامني الذي يوضع من الفرّاشة، «في درب التضامن»، يُبسط هنا.",
    "Un arganier": "شجرة أركان",
    "Un arganier. Il donne à qui sait attendre — et mieux encore à ceux qui récoltent ensemble.": "شجرة أركان. تعطي لمن يعرف الانتظار — وأكثر لمن يجني معًا.",
    "Un puits": "بئر",
    "Un puits. Au douar, on ne le creuse jamais seul.": "بئر. في الدوار، لا يحفره أحد وحده.",
    "Dis ce qu'est ton projet : une coopérative, une association, une entreprise sociale, un projet RSE, une initiative de quartier — ou une idée.":
      "قل ما هو مشروعك: تعاونية، جمعية، مقاولة اجتماعية، مشروع للمسؤولية الاجتماعية، مبادرة في الحي — أو فكرة.",
    "Dis au nom de quelle entreprise tu proposes ce parrainage.": "قل باسم أي مقاولة تقترح هذه الرعاية.",
