    "Ce que ça change": "ما يغيّره", "Ce dont le projet a besoin": "ما يحتاجه المشروع",
    "Je peux aider pour ça": "أستطيع المساعدة في هذا", "Je peux aider": "أستطيع المساعدة",
    "C'est ton projet. Qui veut aider t'écrira : regarde tes messages.": "هذا مشروعك. من يريد المساعدة سيكتب إليك: انظر في رسائلك.",
    "Entre dans la maison pour écrire à son porteur, ou proposer un parrainage.": "ادخل إلى الدار لتكتب إلى صاحب المشروع، أو لتقترح رعاية.",
    "Parrainer (RSE)": "رعاية (مسؤولية اجتماعية)",
    "Son porteur n'est pas encore entré dans la cour : ton aide attendra qu'il y passe. Le bureau, lui, peut déjà faire le lien.":
      "صاحب المشروع لم يدخل الصحن بعد: ستنتظر مساعدتك حتى يمرّ به. أما المكتب، فيستطيع الربط منذ الآن.",
    "Ta proposition de parrainage": "اقتراحك للرعاية",
    "Une entreprise peut adopter ce projet : un financement, un local, du mentorat, des bénévoles de ses équipes. Ta proposition part au bureau de la maison : il vérifie, fait le lien avec le porteur, et grave à la Rkhama l'entreprise qui s'engage.":
      "يمكن لمقاولة أن تتبنّى هذا المشروع: تمويل، مقرّ، توجيه، متطوّعون من فرقها. يصل اقتراحك إلى مكتب الدار: يتحقّق، ويربط بصاحب المشروع، وينقش على الرخامة اسم المقاولة التي تلتزم.",
