    "Au Derb, pas de prix et pas d'affaire : ton projet dit ce qu'il change et ce dont il a besoin. La zawia n'y prend rien.":
      "في الدرب، لا ثمن ولا صفقة: مشروعك يقول ما يغيّره وما يحتاجه. لا تأخذ الزاوية شيئًا.",
    "Ce qu'est ton projet": "ما هو مشروعك", "Choisis…": "اختر…", "Où tu en es": "أين وصلت",
